import test from "node:test";
import assert from "node:assert/strict";
import {intentDigest,signDecisionReceipt,verifyDecisionReceipt,consumeDecisionReceipt} from "../receipt.mjs";
const keys=await crypto.subtle.generateKey({name:"ECDSA",namedCurve:"P-256"},false,["sign","verify"]);
const spki=Buffer.from(await crypto.subtle.exportKey("spki",keys.publicKey)).toString("base64url");
const authority={keys:[{keyId:"fixture",spki}],maxTtlSeconds:120,consumeUrl:"https://fixture.invalid/mi/consume"};
const intent={requestId:"fixture-request",address:"fixture-account",network:{chainId:"spherio-1"},payload:{amount:"100",priceDisplay:0.1},origin:"https://fixture.invalid"};
const payload={protocol:"spherio-mi-v1",keyId:"fixture",status:"RESERVED",decision:"PASS",executionAllowed:true,authorizationId:"fixture-id",policyVersion:"FIXTURE-MI-1",intentDigest:await intentDigest(intent),account:intent.address,chainId:intent.network.chainId,issuedAt:new Date(Date.now()-1000).toISOString(),expiresAt:new Date(Date.now()+60000).toISOString(),observationHeight:"1",observationBlockHash:"fixture-block",provenanceDigest:"fixture-provenance"};
const receipt=await signDecisionReceipt(payload,keys.privateKey);
test("valid signed receipt authorizes only its exact approved intent",async()=>{assert.equal((await verifyDecisionReceipt(receipt,intent,authority)).authorizationId,payload.authorizationId);await assert.rejects(()=>verifyDecisionReceipt(receipt,{...intent,origin:"https://attacker.invalid"},authority),/MISMATCH/);await assert.rejects(()=>verifyDecisionReceipt(receipt,{...intent,payload:{amount:"101"}},authority),/MISMATCH/);await assert.rejects(()=>verifyDecisionReceipt(receipt,intent,{keys:[],maxTtlSeconds:120}),/NOT_CONFIGURED/);});
test("forged, stale, wrong-chain, wrong-account and unbound provenance receipts reject",async()=>{await assert.rejects(()=>verifyDecisionReceipt({...receipt,signature:receipt.signature.slice(0,-4)+"AAAA"},intent,authority),/SIGNATURE/);for(const patch of [{expiresAt:new Date(0).toISOString()},{chainId:"other"},{account:"other"},{observationHeight:null},{executionAllowed:true,decision:"BLOCK"}]){const changed=await signDecisionReceipt({...payload,...patch},keys.privateKey);await assert.rejects(()=>verifyDecisionReceipt(changed,intent,authority));}});
test("backend consumption requires a newly signed consumed record, never a success boolean",async()=>{let count=0;const consumed=await signDecisionReceipt({...payload,status:"CONSUMED"},keys.privateKey);const result=await consumeDecisionReceipt(receipt,intent,authority,async()=>{count++;return {ok:true,json:async()=>consumed};});assert.equal(result.status,"CONSUMED");assert.equal(count,1);await assert.rejects(()=>consumeDecisionReceipt(receipt,intent,authority,async()=>({ok:true,json:async()=>({ok:true})})),/MISMATCH/);await assert.rejects(()=>consumeDecisionReceipt(receipt,intent,{...authority,consumeUrl:"http://fixture.invalid"},async()=>{throw Error("must not run")}),/ORIGIN/);});
